	if value, ok := _c.mutation.PublishedRenderArtifactID(); ok {
		_spec.SetField(contestannouncement.FieldPublishedRenderArtifactID, field.TypeUUID, value)
		_node.PublishedRenderArtifactID = &value
	}
	if value, ok := _c.mutation.Version(); ok {
		_spec.SetField(contestannouncement.FieldVersion, field.TypeInt64, value)
		_node.Version = value
	}
	if value, ok := _c.mutation.ScheduledFor(); ok {
		_spec.SetField(contestannouncement.FieldScheduledFor, field.TypeTime, value)
		_node.ScheduledFor = &value
	}
	if value, ok := _c.mutation.PublishedAt(); ok {
		_spec.SetField(contestannouncement.FieldPublishedAt, field.TypeTime, value)
		_node.PublishedAt = &value
	}
	if value, ok := _c.mutation.WithdrawnAt(); ok {
		_spec.SetField(contestannouncement.FieldWithdrawnAt, field.TypeTime, value)
		_node.WithdrawnAt = &value
	}
	if nodes := _c.mutation.ContestIDs(); len(nodes) > 0 {
		edge := &sqlgraph.EdgeSpec{
			Rel:     sqlgraph.M2O,
			Inverse: true,
			Table:   contestannouncement.ContestTable,
			Columns: []string{contestannouncement.ContestColumn},
			Bidi:    false,
			Target: &sqlgraph.EdgeTarget{
				IDSpec: sqlgraph.NewFieldSpec(contest.FieldID, field.TypeUUID),
			},
		}
		for _, k := range nodes {
			edge.Target.Nodes = append(edge.Target.Nodes, k)
		}
		_node.ContestID = nodes[0]
		_spec.Edges = append(_spec.Edges, edge)
	}
